/**
 * Notification Model — SRU-08
 *
 * Persists in-app notifications generated by all 20 system lifecycle events:
 *  - Pool & MOQ milestones (MOQ_REACHED_LOCKED, EARLY_MOQ_LOCK, EXPIRED_72H_UNDER_MOQ, etc.)
 *  - Pricing snapshot approval cycles (SNAPSHOT_APPROVAL_REQUIRED, APPROVAL_INVALIDATED)
 *  - Payments & automated refunds (PAYMENT_VERIFIED, REFUND_COMPLETED, etc.)
 *  - Order confirmations, dispatches, and fulfillment.
 *
 * Enforces:
 *  - Recipient-scoped with unread tracking (isRead, readAt).
 *  - Indexed on { recipientUserId: 1, isRead: 1, createdAt: -1 } for fast feed queries.
 *  - Non-throwing try/catch boundary protects all calling mutations.
 */

export const NOTIFICATION_TYPES = [
  "POOL_CREATED",
  "POOL_JOINED",
  "PAYMENT_VERIFIED",
  "PAYMENT_FAILED",
  "QUANTITY_UPDATED",
  "MOQ_MILESTONE",
  "MOQ_REACHED_LOCKED",
  "EARLY_MOQ_LOCK",
  "EXPIRED_72H_UNDER_MOQ",
  "UNDER_MOQ_DECISION_REQUIRED",
  "DECISION_DEADLINE_APPROACHING",
  "SUPPLIER_QUOTE_REVISED",
  "SNAPSHOT_APPROVAL_REQUIRED",
  "APPROVAL_INVALIDATED",
  "REFUND_INITIATED",
  "REFUND_COMPLETED",
  "REFUND_FAILED",
  "ORDER_CONFIRMED",
  "ORDER_REJECTED",
  "ORDER_STATUS_UPDATED",
];

import mongoose from "mongoose";

const notificationSchema = new mongoose.Schema(
  {
    recipientUserId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "User",
      required: true,
      index: true,
    },
    shopId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Shop",
      default: null,
      index: true,
    },
    poolId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "GroupBuyPool",
      default: null,
    },
    relatedOrderId: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Order",
      default: null,
      index: true,
    },
    type: {
      type: String,
      enum: NOTIFICATION_TYPES,
      required: true,
    },
    title: {
      type: String,
      required: true,
      trim: true,
    },
    message: {
      type: String,
      required: true,
      trim: true,
    },
    linkUrl: {
      type: String,
      default: null,
    },
    isRead: {
      type: Boolean,
      default: false,
      index: true,
    },
    readAt: {
      type: Date,
      default: null,
    },
    metadata: {
      type: mongoose.Schema.Types.Mixed,
      default: {},
    },
  },
  {
    timestamps: true,
  }
);

// High-performance feed index: fetches unread & recent notifications in a single scan
notificationSchema.index({ recipientUserId: 1, isRead: 1, createdAt: -1 });

export const Notification = mongoose.model("Notification", notificationSchema);
export default Notification;
